insert into public.cs_lessons(id,position,title,description,reading,minutes,xp,journey_id,journey_position,unit_index,reading_cards,checklist,sources,reviewed_at) values ('own-small-costs',310,'Notice the small costs','Practise adding up everyday spending.','Practice example: Jo buys a £3 snack on five days. That adds up to £15. These are invented amounts, not a recommended spending limit. Small purchases can be easy to forget. Writing them down can help explain where your money went. You decide which purchases matter to you. A spending record is information, not a reason to feel guilty.',3,30,'independent',6,3,'["Practice example: Jo buys a £3 snack on five days. That adds up to £15. These are invented amounts, not a recommended spending limit.", "Small purchases can be easy to forget. Writing them down can help explain where your money went.", "You decide which purchases matter to you. A spending record is information, not a reason to feel guilty."]'::jsonb,'["Try the example on paper at your own pace."]'::jsonb,'[]'::jsonb,null) on conflict (id) do nothing;
insert into public.cs_lessons(id,position,title,description,reading,minutes,xp,journey_id,journey_position,unit_index,reading_cards,checklist,sources,reviewed_at) values ('own-weekly-check',311,'Do a five-minute money check','Build a simple habit for reviewing your plan.','Practice example: Lee has £100 available and a known £40 payment due before more money arrives. Reserving that payment leaves £60 for other costs. A short check can include your available balance, payments still to come and any spending you have not yet recorded. Avoid counting the same money twice. If a figure does not look right, check the details before changing your plan. You can make notes and ask someone you trust to help you understand them.',3,30,'independent',7,3,'["Practice example: Lee has £100 available and a known £40 payment due before more money arrives. Reserving that payment leaves £60 for other costs.", "A short check can include your available balance, payments still to come and any spending you have not yet recorded. Avoid counting the same money twice.", "If a figure does not look right, check the details before changing your plan. You can make notes and ask someone you trust to help you understand them."]'::jsonb,'["Try the example on paper at your own pace."]'::jsonb,'[]'::jsonb,null) on conflict (id) do nothing;
insert into public.cs_questions(id,lesson_id,position,prompt,options,correct_index,explanation) values ('own-small-costs-1','own-small-costs',1,'What is £3 spent on five days?','["£8", "£15", "£30"]'::jsonb,1,'£3 multiplied by five is £15.') on conflict (id) do nothing;
insert into public.cs_questions(id,lesson_id,position,prompt,options,correct_index,explanation) values ('own-small-costs-2','own-small-costs',2,'What could help Jo remember small purchases?','["Write them down", "Ignore them", "Guess at the end of the year"]'::jsonb,0,'A short record makes spending easier to see.') on conflict (id) do nothing;
insert into public.cs_questions(id,lesson_id,position,prompt,options,correct_index,explanation) values ('own-small-costs-3','own-small-costs',3,'What is the purpose of keeping a spending record?','["To blame yourself", "To stop every enjoyable purchase", "To understand your choices"]'::jsonb,2,'A record helps you make choices that fit your situation.') on conflict (id) do nothing;
insert into public.cs_questions(id,lesson_id,position,prompt,options,correct_index,explanation) values ('own-weekly-check-1','own-weekly-check',1,'Lee has £100 and reserves £40. What remains?','["£140", "£60", "£40"]'::jsonb,1,'£100 minus £40 leaves £60.') on conflict (id) do nothing;
insert into public.cs_questions(id,lesson_id,position,prompt,options,correct_index,explanation) values ('own-weekly-check-2','own-weekly-check',2,'What should a weekly check include?','["Only yesterday’s balance", "Only money already spent", "Payments still to come"]'::jsonb,2,'Upcoming payments can reduce what is available to spend.') on conflict (id) do nothing;
insert into public.cs_questions(id,lesson_id,position,prompt,options,correct_index,explanation) values ('own-weekly-check-3','own-weekly-check',3,'A figure seems unfamiliar. What is a useful first step?','["Check its details", "Assume it must be correct", "Forget about it"]'::jsonb,0,'Checking the details helps you understand what the figure represents.') on conflict (id) do nothing;
